from pathlib import Path


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text()
    if new in text:
        return
    if old not in text:
        raise SystemExit(f'Expected text not found in {path}: {old[:80]!r}')
    path.write_text(text.replace(old, new, 1))


